using ConjuntoInteligente.PbBridge.Contracts.Dtos; using Microsoft.AspNetCore.Mvc; using Microsoft.Extensions.Caching.Memory;
namespace ConjuntoInteligente.PbBridge.Controllers;
[Route("pb/v1/catalogos")] public sealed class PbCatalogosController:PbBaseController{private readonly IMemoryCache _cache;public PbCatalogosController(IMemoryCache cache)=>_cache=cache;
 [HttpGet("estados-orden")] public IActionResult EstadosOrden()=>PbOk(Cached("cat:estados",()=>new PbCatalogDto{Dominio="estados-orden",Valores=[new(){Clave="scheduled",Etiqueta="Programado"},new(){Clave="in_progress",Etiqueta="En proceso"},new(){Clave="pending_quote",Etiqueta="Por cotizar"},new(){Clave="pending_approval",Etiqueta="Por aprobar"},new(){Clave="critical",Etiqueta="Crítico"},new(){Clave="blocked",Etiqueta="Bloqueado"},new(){Clave="completed",Etiqueta="Completado"},new(){Clave="cancelled",Etiqueta="Cancelado"}]}));
 [HttpGet("categorias")] public IActionResult Categorias()=>PbOk(Cached("cat:categorias",()=>new PbCatalogDto{Dominio="categorias",Valores=[new(){Clave="iluminacion",Etiqueta="Iluminación"},new(){Clave="electrico",Etiqueta="Eléctrico"},new(){Clave="hidrosanitario",Etiqueta="Hidrosanitario"},new(){Clave="areas_verdes",Etiqueta="Áreas verdes"},new(){Clave="parqueaderos",Etiqueta="Parqueaderos"},new(){Clave="seguridad",Etiqueta="Seguridad"},new(){Clave="edificacion",Etiqueta="Edificación"},new(){Clave="ascensores",Etiqueta="Ascensores"},new(){Clave="piscina",Etiqueta="Piscina"},new(){Clave="contra_incendio",Etiqueta="Contra incendio"},new(){Clave="telecomunicaciones",Etiqueta="Telecomunicaciones"},new(){Clave="unknown",Etiqueta="Otro"}]}));
 [HttpGet("severidades")] public IActionResult Severidades()=>PbOk(Cached("cat:severidades",()=>new PbCatalogDto{Dominio="severidades",Valores=[new(){Clave="low",Etiqueta="Baja"},new(){Clave="medium",Etiqueta="Media"},new(){Clave="high",Etiqueta="Alta"},new(){Clave="critical",Etiqueta="Crítica"}]}));
 private PbCatalogDto Cached(string key,Func<PbCatalogDto> factory)=>_cache.GetOrCreate(key,entry=>{entry.AbsoluteExpirationRelativeToNow=TimeSpan.FromMinutes(10);return factory();})!;}
